def routes():
    out, seen = [], set()
    for f in ["app.ts", "routes-platform.ts"]:
        s = (ROOT / "apps/api/src" / f).read_text()
        for m in re.finditer(r'app\.(get|post)\(\s*"([^"]+)"', s):
            out.append((m.group(1).upper(), m.group(2)))
        for m in re.finditer(r'\bact\(\s*"([^"]+)"', s):
            out.append(("POST", m.group(1)))
        for m in re.finditer(r'act\(\s*\n\s*"([^"]+)"', s):
            out.append(("POST", m.group(1)))
    return [r for r in out if not (r in seen or seen.add(r))]


def threats():
    rows = []
    for line in (ROOT / "docs/threat-model.md").read_text().split("\n"):
        if line.startswith("| T"):
            c = [x.strip() for x in line.strip("|").split("|")]
            status = c[3]
            rows.append([c[0], c[1], c[2], status])
    return rows


